window.__finlexDocLoaded(10054,{"id":10054,"articles":[{"id":1000266,"no":"Overview","heading":"Official Overview & Scope (IFRS Foundation)","text":"IFRIC 5 addresses how an entity accounts for its interests in a fund established to decommission assets or to perform environmental restoration or rehabilitation. It also addresses how the entity accounts for any rights to receive reimbursements from such funds and any obligations to make potential additional contributions.","seq":0},{"id":1000267,"no":"History","heading":"Standard History & Amendments","text":"In December 2004 the International Accounting Standards Board issued IFRIC 5 Rights to Interests arising from Decommissioning, Restoration and Environmental Rehabilitation Funds. It was developed by the Interpretations Committee.\n\nOther Standards have made minor consequential amendments to IFRIC 5. They include IFRS 10 Consolidated Financial Statements (issued May 2011), IFRS 11 Joint Arrangements (issued May 2011), IFRS 9 Financial Instruments (Hedge Accounting and amendments to IFRS 9, IFRS 7 and IAS 39) (issued November 2013), IFRS 9 Financial Instruments (issued July 2014) and Amendments to References to the Conceptual Framework in IFRS Standards (issued March 2018).","seq":1},{"id":1000268,"no":"Support","heading":"Related Projects & Implementation Support","text":"[Related active projects]\n[Related completed projects]\n[Related IFRS Standards]\nIAS 37 Provisions, Contingent Liabilities and Contingent Assets\n[Related IFRIC Interpretations]\n[Unconsolidated amendments]\n[Implementation support]\nIFRIC 5 Rights to Interests arising from Decommissioning Restoration and Environmental Rehabilitation Funds","seq":2},{"id":1000269,"no":"References","heading":"Official Text Link & Public Practical Guidance","text":"Official IFRS Foundation Page (English): https://www.ifrs.org/issued-standards/list-of-standards/ifric-5-rights-to-interests-arising-from-decommissioning-restoration-and-environmental/\nAccess Note: Free access to the unaccompanied text of IFRS Accounting Standards on ifrs.org requires a free registered IFRS.org account; Basis for Conclusions and Illustrative Examples require an IFRS Digital Subscription.\nPublic Companion Overview: KPMG Insights into IFRS — An Overview (Sept 2026): https://assets.kpmg.com/content/dam/kpmgsites/xx/pdf/ifrg/2026/isg-2026-insights-an-overview.pdf","seq":3}]});
